pm=[mkhead('Pillar &amp; Frame · Partner Marketing on Vendor Funds',
 'Pillar &amp; Frame runs the partner marketing function for resellers, installers and dealers with co-op or MDF funds. One filming day a quarter, placement, reporting and a claim package that files cleanly.'),
 '<body><a class="skip" href="#main">Skip to content</a><div class="dark-top"><header class="wrap"><a class="brand" href="#main">pillar<span class="amp">&amp;</span>frame.</a><span class="location">Central Ohio</span><nav aria-label="Main navigation"><a href="#offer">What we run</a><a href="#pricing">Pricing</a><a href="#faq">FAQ</a>'+cta('Book a fund audit')+'</nav></header></div><main id="main">']
